import copy


class OrderNotFound(KeyError):
    pass


class InMemoryOrderRepository:
    """Stands in for the database: what is saved is what later reads see.

    A real database hands back a fresh row each time, so this does too.
    """

    def __init__(self):
        self._orders = {}

    def save(self, order):
        self._orders[order.order_id] = copy.deepcopy(order)

    def get(self, order_id):
        try:
            return copy.deepcopy(self._orders[order_id])
        except KeyError:
            raise OrderNotFound(order_id)

